'use strict';

function receive(amount) {
  return { type: 'RECEIVE', amount };
}

function dispatch(amount) {
  return { type: 'DISPATCH', amount };
}

function stockReducer(state = { units: 0 }, action) {
  if (
    state === null ||
    typeof state !== 'object' ||
    Array.isArray(state) ||
    !Number.isInteger(state.units) ||
    state.units < 0
  ) {
    throw new TypeError('invalid state');
  }
  if (action === null || typeof action !== 'object' || Array.isArray(action)) {
    throw new TypeError('invalid action');
  }
  if (action.type !== 'RECEIVE' && action.type !== 'DISPATCH') {
    return state;
  }
  if (!Number.isInteger(action.amount) || action.amount < 0) {
    throw new TypeError('amount must be a non-negative integer');
  }
  if (action.type === 'RECEIVE') {
    return { units: state.units + action.amount };
  }
  return { units: state.units - action.amount };
}

module.exports = { stockReducer, receive, dispatch };

