'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['dispatch', 'receive', 'stockReducer']);
const { stockReducer, receive, dispatch } = api;

assert.deepStrictEqual(receive(4), { type: 'RECEIVE', amount: 4 });
assert.deepStrictEqual(dispatch(3), { type: 'DISPATCH', amount: 3 });
assert.strictEqual(receive('4').amount, '4');
assert.strictEqual(dispatch(null).amount, null);
assert.notStrictEqual(receive(1), receive(1));

const initial = stockReducer(undefined, { type: 'UNKNOWN', amount: 'ignored' });
assert.deepStrictEqual(initial, { units: 0 });

{
  const state = { units: 5 };
  const action = receive(4);
  const next = stockReducer(state, action);
  assert.deepStrictEqual(next, { units: 9 });
  assert.notStrictEqual(next, state);
  assert.deepStrictEqual(state, { units: 5 });
  assert.deepStrictEqual(action, { type: 'RECEIVE', amount: 4 });
}

{
  const state = { units: 5 };
  assert.deepStrictEqual(stockReducer(state, dispatch(2)), { units: 3 });
  assert.deepStrictEqual(stockReducer(state, dispatch(99)), { units: 0 });
  assert.deepStrictEqual(state, { units: 5 });
}

for (const type of ['RECEIVE', 'DISPATCH']) {
  const state = { units: 7 };
  const next = stockReducer(state, { type, amount: 0 });
  assert.deepStrictEqual(next, { units: 7 });
  assert.notStrictEqual(next, state);
}

{
  const state = { units: 8 };
  for (const action of [
    { type: 'OTHER', amount: -1 },
    { amount: Symbol('ignored') },
    { type: null, amount: 1.5 }
  ]) {
    assert.strictEqual(stockReducer(state, action), state);
  }
}

for (const invalidState of [
  null,
  [],
  1,
  {},
  { units: -1 },
  { units: 1.5 },
  { units: NaN },
  { units: Infinity },
  { units: '2' }
]) {
  assert.throws(() => stockReducer(invalidState, { type: 'OTHER' }), TypeError);
}

for (const invalidAction of [null, undefined, [], 'RECEIVE', 3]) {
  assert.throws(() => stockReducer({ units: 1 }, invalidAction), TypeError);
}

for (const type of ['RECEIVE', 'DISPATCH']) {
  for (const amount of [-1, 1.5, NaN, Infinity, '2', null, undefined]) {
    assert.throws(() => stockReducer({ units: 2 }, { type, amount }), TypeError);
  }
}

